@media (max-width: 768px) {
    .header h1 {
        font-size: 32px;
    }

    .subtitle {
        font-size: 14px;
    }

    .image-card {
        margin: 0 -20px;
        border-radius: 8px;
    }

    .image-container {
        height: 240px;
    }

    .image-info {
        padding: 24px;
    }

    .modal-content {
        width: 95%;
    }

    .modal-footer {
        flex-direction: column-reverse;
    }

    .modal-footer .btn {
        width: 100%;
    }
}

@media (max-width: 480px) {
    body {
        padding: 12px;
    }

    .header {
        margin-bottom: 32px;
    }

    .header h1 {
        font-size: 24px;
    }

    .preview-section {
        max-width: 100%;
    }

    .image-info h2 {
        font-size: 20px;
    }

    .delete-btn {
        padding: 12px 16px;
        font-size: 13px;
    }

    .modal-header,
    .modal-body,
    .modal-footer {
        padding: 16px;
    }
}
