    height: 100%;
    object-fit: cover;
    display: block;
}

.image-info {
    padding: 32px;
}

.image-info h2 {
    font-size: 24px;
    font-weight: 600;
    color: #1a2332;
    margin-bottom: 8px;
}

.image-details {
    font-size: 14px;
    color: #999;
    margin-bottom: 24px;
}

