.btn {
    padding: 12px 24px;
    border: none;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.delete-btn {
    width: 100%;
    padding: 14px 24px;
    background: #fff5f5;
    color: #e53e3e;
    border: 2px solid #feb2b2;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.delete-btn:hover {
    background: #fed7d7;
    border-color: #fc8181;
    transform: translateY(-2px);
}

.delete-btn:active {
    transform: translateY(0);
}

.btn-secondary {
    background: #f0f0f0;
