    border: 1px solid #e53e3e;
}

.btn-danger:hover {
    background: #c53030;
    border-color: #c53030;
    box-shadow: 0 4px 12px rgba(229, 62, 62, 0.3);
}

.btn-danger:active {
    background: #a02622;
}

/* Modal Dialog */
.modal-overlay {
